package com.lqq.supportflow.knowledge.infrastructure.persistence;
import com.lqq.supportflow.knowledge.domain.*; import java.time.Instant; import java.util.ArrayList; import java.util.List; import org.springframework.stereotype.Component;
@Component public class MyBatisKnowledgeChunkAdapter implements KnowledgeChunkPort { private final KnowledgeChunkMapper mapper; public MyBatisKnowledgeChunkAdapter(KnowledgeChunkMapper mapper){this.mapper=mapper;} public List<KnowledgeChunk> saveAll(Long tenantId,Long knowledgeBaseId,Long documentId,List<String> contents){Instant now=Instant.now();List<KnowledgeChunk> chunks=new ArrayList<>();for(int index=0;index<contents.size();index++){KnowledgeChunkEntity entity=new KnowledgeChunkEntity();entity.tenantId=tenantId;entity.knowledgeBaseId=knowledgeBaseId;entity.documentId=documentId;entity.chunkNo=index;entity.content=contents.get(index);entity.createdAt=now;mapper.insert(entity);chunks.add(new KnowledgeChunk(entity.id,documentId,index,entity.content));}return chunks;} public long count(Long tenantId,Long knowledgeBaseId,Long documentId){return mapper.selectCount(new com.baomidou.mybatisplus.core.conditions.query.QueryWrapper<KnowledgeChunkEntity>().eq("tenant_id",tenantId).eq("knowledge_base_id",knowledgeBaseId).eq("document_id",documentId));}}
